Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Step([string]$Message) { Write-Host "[HOME REVISI] $Message" -ForegroundColor Cyan }
function Fail-Step([string]$Message) { Write-Host "[HOME REVISI] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Step "Jalankan script ini dari repository Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
Write-Step "Repo: $repoRoot"
$required = @(
  "components/site/formwork/home.tsx",
  "components/site/formwork/local-assets.ts",
  "components/site/formwork/decor.tsx"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { $missing | ForEach-Object { Write-Host "  - $_" -ForegroundColor Yellow }; Fail-Step "File dasar formwork tidak ditemukan." }

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $repoRoot ".lunar-backups/home-static-revision-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
$backupList = @(
  "components/site/formwork/home.tsx",
  "components/site/formwork/local-assets.ts"
)
foreach ($item in $backupList) { if (Test-Path -LiteralPath $item) { $dest = Join-Path $backupRoot $item; $parent = Split-Path -Parent $dest; if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }; Copy-Item -LiteralPath $item -Destination $dest -Force } }
Write-Step "Backup dibuat di $backupRoot"

$payload = @{}
$payload["components/site/formwork/home.tsx"] = ""
$payload["components/site/formwork/local-assets.ts"] = ""
$payload["public/lunar-static/formwork-about-placeholder.svg"] = ""
$payload["public/lunar-static/formwork-detail-01.svg"] = ""
$payload["public/lunar-static/formwork-detail-02.svg"] = ""
$payload["public/lunar-static/formwork-detail-03.svg"] = ""
$payload["public/lunar-static/formwork-detail-04.svg"] = ""
$payload["public/lunar-static/formwork-detail-05.svg"] = ""
$payload["public/lunar-static/formwork-detail-06.svg"] = ""
$payload["public/lunar-static/formwork-hero-placeholder.svg"] = ""
$payload["public/lunar-static/formwork-process-planning.svg"] = ""
$payload["public/lunar-static/formwork-projects-placeholder.svg"] = ""
$payload["public/lunar-static/formwork-services-placeholder.svg"] = ""
$payload["public/lunar-static/formwork-site-note.svg"] = ""

foreach ($entry in $payload.GetEnumerator()) {
  $target = Join-Path $repoRoot $entry.Key
  Write-Utf8NoBom $target (Decode $entry.Value)
  Write-Host "[HOME REVISI] write  $($entry.Key)" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "[HOME REVISI] Revisi home selesai." -ForegroundColor Green
Write-Host "[HOME REVISI] Perubahan utama: process pakai gambar statis lokal, selected work lebih editorial, dan curve kini diberi label." -ForegroundColor Green
Write-Host "[HOME REVISI] Kalau mau ganti visual statis, cukup replace file di public/lunar-static/*.svg atau tambahkan gambar sendiri lalu arahkan di components/site/formwork/local-assets.ts." -ForegroundColor Yellow
Write-Host ""
Write-Host "Lanjutkan validasi:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
Write-Host "  npm run dev"
